import org.junit.Assert;
import org.junit.Test;
import org.traccar.Protocol;
import org.traccar.model.Position;
import io.netty.buffer.Unpooled;

import java.util.TimeZone;

import static org.mockito.Mockito.*;

public class Gt06ProtocolDecoderTest {

    @Test
    public void decodeGpsWithLengthTest() {
        Position position = new Position();
        boolean res = Gt06ProtocolDecoder.decodeGps(position, Unpooled.buffer().writeInt(123), true, TimeZone.getDefault());

        Assert.assertTrue(res);
    }

    @Test
    public void decodeGpsWithoutLengthTest() {
        Position position = new Position();
        boolean res = Gt06ProtocolDecoder.decodeGps(position, Unpooled.buffer().writeInt(123), false, TimeZone.getDefault());

        Assert.assertTrue(res);
    }

    @Test
    public void decodeGpsWithSatellitesTest() {
        Position position = new Position();
        boolean res = Gt06ProtocolDecoder.decodeGps(position, Unpooled.buffer().writeInt(123), true, true, true, TimeZone.getDefault());

        Assert.assertTrue(res);
    }

    @Test
    public void decodeGpsWithoutSatellitesTest() {
        Position position = new Position();
        boolean res = Gt06ProtocolDecoder.decodeGps(position, Unpooled.buffer().writeInt(123), true, false, true, TimeZone.getDefault());

        Assert.assertTrue(res);
    }

    @Test
    public void decodeTest() throws Exception {
        Gt06ProtocolDecoder decoder = new Gt06ProtocolDecoder(new Protocol("gt06"));
        SocketAddress remoteAddress = mock(SocketAddress.class);

        Object result = decoder.decode(null, remoteAddress, Unpooled.buffer().writeInt(123));

        Assert.assertNotNull(result);
    }
}
